'use strict';
// Village tools share the existing simulation clock and save, without extra loops.
function villageProgress(){state.village??={claimed:[],alarm:false,winterSeconds:0};return state.village}
const VILLAGE_GOALS=[{id:'homes',name:'Rosnąca osada: zbuduj 5 domów',reward:50,done:()=>ownCount('dom')>=5},{id:'workers',name:'Pracowita osada: 5 mieszkańców przy pracy',reward:75,done:()=>residents.filter(r=>r.phase==='praca').length>=5},{id:'winter',name:'Spędź 180 sekund zimy w osadzie',reward:100,done:()=>villageProgress().winterSeconds>=180},{id:'defense',name:'Obrona: zbuduj 3 wieże i zwerbuj 5 żołnierzy',reward:100,done:()=>ownCount('wieza')>=3&&armyTotal()>=5}];
function claimVillageGoal(id){const g=VILLAGE_GOALS.find(g=>g.id===id),v=villageProgress();if(!g||v.claimed.includes(id)||!g.done())return false;v.claimed.push(id);state.gold+=g.reward;save();ui();renderVillage();return true}
function setVillageAlarm(active){const v=villageProgress();if(v.alarm===active)return;v.alarm=active;residentRouteQueue=[];residentAssignmentTask=null;for(const r of residents){r.path=[];r.routePending=false;r.phase=active?'schronienie':'odpoczynek';r.wait=0;if(active)requestResidentRoute(r,r.home,'schronienie')}if(active){syncGarrisonActors();const gates=state.buildings.filter(b=>['brama','brama_swoi'].includes(b.type));for(const [i,u] of state.war.guards.entries()){u.alarmHome=u.home;u.alarmOrder=u.order;const g=gates.length?gates[i%gates.length]:state.settled;if(g){u.home=nearbySpot(g.x,g.y+1)||villageOrigin();delete u.order;u.path=[]}}}else{for(const u of state.war.guards){if(u.alarmHome)u.home=u.alarmHome;if(u.alarmOrder)u.order=u.alarmOrder;delete u.alarmHome;delete u.alarmOrder}peopleSignature=''}save();renderVillage();say(active?'Alarm! Mieszkańcy wracają do domów, garnizon osłania bramy.':'Koniec alarmu. Mieszkańcy wracają do pracy.')}
const villageResidentsUpdate=updateResidents;
updateResidents=function(dt){if(!villageProgress().alarm){villageResidentsUpdate(dt);return}processResidentPlanning();for(const r of residents){if(r.routePending)continue;if(r.path.length){const p=r.path[0],dx=p.x-r.x,dy=p.y-r.y,d=Math.hypot(dx,dy),step=65*dt*pathSpeed(r.x,r.y);if(blocked(p.x,p.y)){r.path=[];r.wait=2}else if(d<=step){r.x=p.x;r.y=p.y;r.path.shift()}else{r.x+=dx/d*step;r.y+=dy/d*step}}else if(Math.hypot(r.x-(r.home.x+.5)*T,r.y-(r.home.y+.5)*T)>T/2){r.wait-=dt;if(r.wait<=0)requestResidentRoute(r,r.home,'schronienie')}}};
const villageStep=simulationStep;
simulationStep=function(dt){villageStep(dt);if(state.settled&&seasonIndex()===3)villageProgress().winterSeconds+=dt};
function residentDescription(r){const job=r.job?defs.find(d=>d[0]===r.job.type)?.[2]:'Brak stanowiska';const reason=villageProgress().alarm?'Alarm — wraca do domu':r.routePending?'Planuje drogę':r.phase==='czeka'?'Przejście zablokowane — sprawdź bramy':!r.job?'Brak wolnego dostępnego stanowiska':r.phase;return {name:r.name,job,reason}}
let villageGoalSignature='';
function renderVillage(){const v=villageProgress();$('villageAlarm').textContent=v.alarm?'✓ Zakończ alarm':'⚠ Alarm obronny';const signature=JSON.stringify([v.claimed,VILLAGE_GOALS.map(g=>g.done())]);if(signature!==villageGoalSignature){villageGoalSignature=signature;$('villageGoals').innerHTML=VILLAGE_GOALS.map(g=>`<p>${v.claimed.includes(g.id)?'✓':g.done()?'★':'○'} ${g.name} · ${g.reward} monet <button data-village-goal="${g.id}" ${v.claimed.includes(g.id)||!g.done()?'disabled':''}>${v.claimed.includes(g.id)?'Odebrano':'Odbierz'}</button></p>`).join('')}if(selectedResident!==null){const r=residents.find(r=>r.id===selectedResident);if(r){const info=residentDescription(r);$('residentDetails').textContent=info.name+' · '+info.job+' · '+info.reason}else $('residentDetails').textContent='Mieszkaniec opuścił osadę.'}}
let selectedResident=null;
function openVillage(){renderVillage();$('villagePanel').classList.remove('hidden')}
function exportVillage(){if(!save())return;const blob=new Blob([JSON.stringify({format:'zielona-dolina',version:1,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='zielona-dolina-zapis.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('Pobrano kopię wioski.')}
function validateVillageBackup(text){const data=JSON.parse(text),s=data?.format==='zielona-dolina'&&data.version===1?data.state:null;if(!s||!s.p||![s.p.x,s.p.y].every(n=>Number.isFinite(n)&&n>=0&&n<N*T)||!Array.isArray(s.buildings)||s.buildings.length>N*N||!Array.isArray(s.cut)||!Array.isArray(s.seen)||s.seen.length>N*N||s.cut.length>N*N)throw Error('Nieprawidłowy plik zapisu.');for(const k of ['wood','stone','food','gold','time'])if(!Number.isFinite(s[k])||s[k]<0)throw Error('Nieprawidłowe zasoby.');for(const b of s.buildings)if(!Number.isInteger(b.x)||!Number.isInteger(b.y)||b.x<0||b.y<0||b.x>=N||b.y>=N||!['start',...defs.map(d=>d[0]),'ruiny'].includes(b.type))throw Error('Nieprawidłowy budynek.');return s}
$('villageOpen').onclick=openVillage;$('villageClose').onclick=()=>$('villagePanel').classList.add('hidden');$('villageAlarm').onclick=()=>setVillageAlarm(!villageProgress().alarm);$('backupExport').onclick=exportVillage;$('backupImport').onclick=()=>$('backupFile').click();$('backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('Plik jest za duży.');const s=validateVillageBackup(await f.text());if(!confirm('Wczytać kopię i zastąpić obecną wioskę? Najpierw pobierz jej zapis do pliku.'))return;localStorage.setItem(KEY,JSON.stringify(s));location.reload()}catch(err){say('Nie wczytano kopii: '+err.message)}finally{e.target.value=''}};$('villageGoals').onclick=e=>{const b=e.target.closest('[data-village-goal]');if(b)claimVillageGoal(b.dataset.villageGoal)};
setInterval(()=>{if(!$('villagePanel').classList.contains('hidden'))renderVillage()},1000);
function buildLine(a,b){const out=[],dx=Math.abs(b.x-a.x),dy=Math.abs(b.y-a.y),sx=a.x<b.x?1:-1,sy=a.y<b.y?1:-1;let x=a.x,y=a.y,err=dx-dy;for(let i=0;i<64;i++){out.push({x,y});if(x===b.x&&y===b.y)break;const e=2*err;if(e>-dy){err-=dy;x+=sx}if(e<dx){err+=dx;y+=sy}}return out}
let villageBuildDrag=null;
const villageDown=c.onpointerdown,villageMove=c.onpointermove,villageUp=c.onpointerup,villageCancel=c.onpointercancel;
c.onpointerdown=e=>{if(['palisada','sciezka'].includes(mode)&&!e.button){const p=worldPoint(e);villageBuildDrag={mode,a:{x:Math.floor(p.x/T),y:Math.floor(p.y/T)},b:{x:Math.floor(p.x/T),y:Math.floor(p.y/T)}};c.setPointerCapture?.(e.pointerId);return}if(!mode&&!commandDraft&&!patrolDraft&&!navalDraft&&!selectedActors().length){const p=worldPoint(e),r=residents.find(r=>Math.hypot(p.x-r.x,p.y-(r.y-12))<18);if(r){selectedResident=r.id;openVillage();return}}villageDown(e)};
c.onpointermove=e=>{villageMove?.(e);if(villageBuildDrag){const p=worldPoint(e);villageBuildDrag.b={x:Math.floor(p.x/T),y:Math.floor(p.y/T)}}};
c.onpointerup=e=>{if(!villageBuildDrag){villageUp?.(e);return}const d=villageBuildDrag;villageBuildDrag=null;if(c.hasPointerCapture?.(e.pointerId))c.releasePointerCapture(e.pointerId);if(mode!==d.mode)return;const line=buildLine(d.a,d.b);let count=0;simulationActive=true;try{for(const p of line){const n=state.buildings.length;build(p.x,p.y);if(state.buildings.length>n)count++}}finally{simulationActive=false}if(count)save();say('Zbudowano odcinków: '+count+' / '+line.length)};
c.onpointercancel=()=>{villageBuildDrag=null;villageCancel?.()};window.addEventListener('keydown',e=>{if(e.key==='Escape')villageBuildDrag=null});
const villageDraw=draw;
draw=function(){villageDraw();if(!villageBuildDrag)return;const d=villageBuildDrag,line=buildLine(d.a,d.b),def=defs.find(x=>x[0]===d.mode);ctx.save();ctx.translate(innerWidth/2,innerHeight*.46);ctx.scale(zoom,zoom);ctx.translate(-state.p.x,-state.p.y);for(const p of line){ctx.fillStyle=Math.hypot(p.x+.5-state.p.x/T,p.y+.5-state.p.y/T)<=7?'#f7d87988':'#e87d6588';ctx.fillRect(p.x*T,p.y*T,T,T)}ctx.restore();ctx.fillStyle='#18382f';ctx.fillRect(innerWidth/2-190,180,380,42);ctx.fillStyle='#fff0c5';ctx.font='16px system-ui';ctx.textAlign='center';ctx.fillText(line.length+' pól · '+line.length*def[3]+' drewna · '+line.length*(d.mode==='sciezka'&&state.life?.paving?3:def[4])+' kamienia',innerWidth/2,207);ctx.textAlign='start'};
villageProgress();

if(villageProgress().alarm){residentAssignmentTask=null;residentRouteQueue=[];for(const r of residents){r.routePending=false;r.path=[];r.phase='schronienie';requestResidentRoute(r,r.home,'schronienie')}}
